// Builds js/icons.js: one SVG per product from the open-source icon sets listed in SETS, picked by tools/icon-map.mjs.
// Needs the @iconify-json packages installed next to this script's node_modules (see tools/README-icons.md), but the
// game itself only ships the generated file. Usage: node tools/build-icons.mjs [--check]
import { createRequire } from "module";
import { readFileSync, writeFileSync } from "fs";
import { fileURLToPath } from "url";
import { dirname, join } from "path";
import { RULES, FALLBACK } from "./icon-map.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const require = createRequire(process.env.ICON_PKGS ? join(process.env.ICON_PKGS, "x.js") : import.meta.url);
const SETS = { mdi: "Material Design Icons (Apache 2.0)", "game-icons": "Game Icons (CC BY 3.0)", ph: "Phosphor (MIT)", tabler: "Tabler (MIT)" };
const sets = {};
for (const s of Object.keys(SETS)) sets[s] = require("@iconify-json/" + s + "/icons.json");

// Product list straight from js/data.js.
const src = readFileSync(join(here, "../js/data.js"), "utf8");
const win = {}; new Function("window", "SVT", src + "\n;window.SVT = window.SVT || SVT;")(win, win.SVT = win.SVT || {});
const labs = win.SVT.LABS;

const check = process.argv.includes("--check");
const bad = new Set(), used = {}, fell = [], hits = new Map();
const pick = (name) => {
  const n = name.toLowerCase();
  for (const [re, icon] of RULES) if (re.test(n)) { hits.set(re, (hits.get(re) || 0) + 1); return icon; }
  fell.push(name);
  return FALLBACK;
};
const lookup = (id) => {
  const [set, name] = id.split(":");
  const d = sets[set] && sets[set].icons[name];
  if (!d) { bad.add(id); return null; }
  return { body: d.body, w: d.width || sets[set].width || 24, h: d.height || sets[set].height || 24 };
};
const map = {};
labs.forEach((l) => l.products.forEach((p, i) => {
  let id = pick(p);
  if (!lookup(id)) id = FALLBACK;
  map[l.id + ":" + i] = id;
  used[id] = lookup(id);
}));
const unusedRules = RULES.filter((r) => !hits.has(r[0])).map((r) => String(r[0]));
if (bad.size) console.log("MISSING ICONS (" + bad.size + "):\n  " + [...bad].join("\n  "));
if (fell.length) console.log("FELL TO FALLBACK (" + fell.length + "):\n  " + fell.join("\n  "));
if (unusedRules.length) console.log("UNUSED RULES (" + unusedRules.length + "):\n  " + unusedRules.join("\n  "));
console.log("products " + Object.keys(map).length + ", distinct icons " + Object.keys(used).length);
if (check) process.exit(bad.size || fell.length ? 1 : 0);

const out = ["// Generated by tools/build-icons.mjs from tools/icon-map.mjs. Do not edit by hand.",
  "// Icon sets: " + Object.values(SETS).join(", ") + ".",
  "(function () {", "const SVT = window.SVT = window.SVT || {};",
  "SVT.ICON_SETS = " + JSON.stringify(SETS) + ";",
  "SVT.ICONS = " + JSON.stringify(used) + ";",
  "SVT.PRODUCT_ICON = " + JSON.stringify(map) + ";", "})();", ""];
writeFileSync(join(here, "../js/icons.js"), out.join("\n"));
console.log("wrote js/icons.js (" + (out.join("\n").length / 1024).toFixed(0) + " KB)");
